// ОбщийМодуль.упо_СпринтыСервер. Исправляется только проекция индексируемого UID.
// Длина нативного определяемого типа равна 25.
Функция ДанныеНативногоРегистра(ИмяРегистра, Ключи)
	Запрос = Новый Запрос("ВЫБРАТЬ ВерсияПлана КАК ВерсияПлана,
		|ВЫРАЗИТЬ(ЭлементУИД КАК СТРОКА(25)) КАК ЭлементУИД
		|ПОМЕСТИТЬ Ключи ИЗ &Ключи КАК Ключи
		|ИНДЕКСИРОВАТЬ ПО ВерсияПлана, ЭлементУИД;
		|ВЫБРАТЬ Данные.* ИЗ РегистрСведений." + ИмяРегистра + " КАК Данные
		|ВНУТРЕННЕЕ СОЕДИНЕНИЕ Ключи КАК Ключи
		|ПО Данные.ВерсияПлана = Ключи.ВерсияПлана И Данные.ЭлементУИД = Ключи.ЭлементУИД");
	Запрос.УстановитьПараметр("Ключи", Ключи);
	Результат = Запрос.Выполнить().Выгрузить();
	Результат.Индексы.Добавить("ВерсияПлана,ЭлементУИД");
	Возврат Результат;
КонецФункции

Процедура ПроверитьКандидатовДопусковСпринтов(Кандидаты)
	Если ТипЗнч(Кандидаты) <> Тип("ТаблицаЗначений") Тогда
		ВызватьИсключение НСтр("ru = 'Некорректная таблица кандидатов допуска спринтов.'");
	КонецЕсли;
	Для Каждого ИмяКолонки Из СтрРазделить("ВерсияПлана,ЭлементУИД,Спринт", ",") Цикл
		Если Кандидаты.Колонки.Найти(ИмяКолонки) = Неопределено Тогда
			ВызватьИсключение НСтр("ru = 'Некорректная таблица кандидатов допуска спринтов.'");
		КонецЕсли;
	КонецЦикла;
	Для Каждого Кандидат Из Кандидаты Цикл
		ПроверитьКлючРаботы(КлючЭлемента(Кандидат.ВерсияПлана, Кандидат.ЭлементУИД));
		Если ТипЗнч(Кандидат.Спринт) <> Тип("СправочникСсылка.упо_Спринты") Тогда
			ВызватьИсключение НСтр("ru = 'Некорректный спринт кандидата допуска.'");
		КонецЕсли;
	КонецЦикла;
КонецПроцедуры

Процедура ПроверитьКлючРаботы(КлючРаботы)
	Если ТипЗнч(КлючРаботы) <> Тип("Структура") Или Не КлючРаботы.Свойство("ВидРаботы") Тогда
		ВызватьИсключение НСтр("ru = 'Некорректный ключ работы.'");
	КонецЕсли;
	Если КлючРаботы.ВидРаботы = "Задание" Тогда
		Если Не КлючРаботы.Свойство("Задание")
			Или ТипЗнч(КлючРаботы.Задание) <> Тип("СправочникСсылка.упо_Задания")
			Или Не ЗначениеЗаполнено(КлючРаботы.Задание) Тогда
			ВызватьИсключение НСтр("ru = 'Некорректная ссылка задания.'");
		КонецЕсли;
	ИначеЕсли КлючРаботы.ВидРаботы = "ЭлементПлана" Тогда
		Если Не КлючРаботы.Свойство("ВерсияПлана") Или Не КлючРаботы.Свойство("ЭлементУИД")
			Или ТипЗнч(КлючРаботы.ВерсияПлана) <> Тип("СправочникСсылка.упо_ВерсииПланов")
			Или Не ЗначениеЗаполнено(КлючРаботы.ВерсияПлана)
	Или ТипЗнч(КлючРаботы.ЭлементУИД) <> Тип("Строка") Или ПустаяСтрока(КлючРаботы.ЭлементУИД)
			Или СтрДлина(КлючРаботы.ЭлементУИД) > 25 Тогда
			ВызватьИсключение НСтр("ru = 'Некорректный ключ элемента плана.'");
		КонецЕсли;
	Иначе
		ВызватьИсключение НСтр("ru = 'Неизвестный вид работы.'");
	КонецЕсли;
КонецПроцедуры

Функция КлючЭлемента(ВерсияПлана, ЭлементУИД) Экспорт
	Возврат Новый Структура("ВидРаботы,ВерсияПлана,ЭлементУИД", "ЭлементПлана", ВерсияПлана, ЭлементУИД);
КонецФункции

Функция ЕстьМаркер(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Данные.Свойство("Маркер");
КонецФункции

Функция НетВерсии(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Не Данные.Свойство("Версия");
КонецФункции

Функция НаличиеАдреса(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    ЕстьАдрес = Данные.Свойство("Адрес");
    Если Не ЕстьАдрес Тогда
        Возврат "нет";
    КонецЕсли;
    Возврат "есть";
КонецФункции

Функция ПоложительныйОстаток(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Данные.Свойство("Остаток")
        И ТипЗнч(Данные.Остаток) = Тип("Число")
        И Данные.Остаток > 0;
КонецФункции

Функция ЕстьЛюбойКлюч(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Данные.Свойство("Основной") Или Данные.Свойство("Резервный");
КонецФункции

Функция ЕстьКлюч(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Не (Не Данные.Свойство("Ключ"));
КонецФункции

Функция ЕстьФлаг(Данные)
    Перем ЗначениеФлага;
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    ЕстьФлаг = Данные.Свойство("Флаг", ЗначениеФлага);
    Возврат ЕстьФлаг;
КонецФункции

Функция ЕстьЛюбойРеквизит(Данные)
    Если ТипЗнч(Данные) <> Тип("Структура") Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Данные.Свойство("Первый") Или Данные.Свойство("Второй");
КонецФункции
